evidence.quote:
set cd.compustat_qtr;
sic2 = int(sic/100);
if year(datadate) >= 2000;
keep gvkey datadate rdq sic2;

data ibesticker;
	set cd.ibesticker_updated;
	keep gvkey datadate ibesticker;

set ibes.STATSUMU_EPSUS;
where measure = 'EPS' and FISCALP = 'QTR';
ibesticker = ticker;
id = cat(ibesticker,fpedats);
year = year(fpedats);
qtr = qtr(fpedats);
analyst_following = numest;
keep ibesticker fpedats statpers analyst_following id year qtr;

proc sql;
	create table tmp.rec as
	select a.gvkey, a.rdq, b.amaskcd as analys, b.anndats as recdate, b.IRECCD as rec
	from firms as a, ibes.recddet as b
	where a.ibesticker=b.ticker and b.anndats < a.rdq;
	quit;

data rec; set tmp.rec; id = cat(gvkey,rdq,analys);

proc sort data=rec; by id descending recdate; run;
data tmp.rec; set rec; by id; if first.id; drop id; run; quit;

proc sql;
        create table tmp.earn as
        select a.gvkey, a.rdq, b.pends, b.value as actual, anndats as ea_date
        from firms as a, ibes.actu_epsus as b
        where measure = 'EPS' and pdicity = 'QTR' and a.ibesticker = b.ticker
                        and intnx('day',a.datadate,-5) <= b.pends <= intnx('day',a.datadate,+5);

proc sql;
        create table tmp.prc_2_days_before_cc as
        select a.gvkey, a.confcalldate, b.date, b.prc
        from firms as a, crsp.dsf as b
        where a.permno=b.permno and intnx('weekday',a.confcalldate,-10) <= b.date <= intnx('weekday',a.confcalldate,-2);

data firms;
	set tmp.firms;
	if gvkey ne '';
	if ibesticker ne '';
	if datadate ne .;
	if rdq ne .;
	keep gvkey ibesticker confcalldate datadate datadate_plus1 rdq rdq_plus1 sic2;
	run;

proc sort data=firms nodupkey; by gvkey rdq; run;

data afq; set tmp.afq;
data excluded; set tmp.excluded;

proc sort data=afq; by ibesticker fpedats analys fpi actdats acttims; run;
proc sort data=excluded nodupkey; by ibesticker fpedats analys fpi actdats acttims; run;

data afq1 afq2;
        merge afq(in=a) excluded(in=b);
        by ibesticker fpedats analys fpi actdats acttims;
        if a eq 1 and b eq 1 then output afq1;
        if a eq 1 and b eq 0 then output afq2;

data afq1; set afq1; excluded = 1;
data afq2; set afq2; excluded = 0;

data tmp.afq; set afq1 afq2; drop fpi actdats acttims; run; quit;

**** NUMBER OF COMPANIES COVERED BY THE ANALYST OVER THE PREVIOUS YEAR ****;

data analysts; set afq; keep analys rdq;
proc sort data=analysts nodupkey; by analys rdq; run;

proc sql;
        create table tmp.num_companies as
        select distinct a.analys, a.rdq, b.ticker
        from analysts as a, ibes.detu_epsus as b
        where a.analys=b.analys and b.measure = 'EPS'
                        and (fpi = '6' or fpi = '7' or fpi = '8' or fpi = '9' or fpi = 'N' or fpi = 'O' or fpi = 'P' or fpi = 'Q' or fpi = 'R' or fpi = 'S' or fpi = 'T' or fpi = 'L' or fpi = 'Y')
						and intnx('day',a.rdq,-365) <= b.anndats < rdq;
        quit;

proc sort data=tmp.num_companies nodupkey; by analys rdq ticker; run;
proc freq data=tmp.num_companies noprint; by analys; tables rdq/out=tmp.num_companies; run;

data tmp.num_companies; set tmp.num_companies; num_companies = count; keep analys rdq num_companies; run; quit;

**** NUMBER OF QUARTERLY FORECASTS ISSUED BY THE ANALYST FOR THE FIRM OVER THE PREVIOUS YEAR ****;

proc sql;
        create table tmp.num_for as
        select a.gvkey, a.rdq, a.analys, b.anndats
        from afq as a, ibes.detu_epsus as b
        where a.ibesticker=b.ticker and a.analys=b.analys and b.measure = 'EPS'
                        and (fpi = '6' or fpi = '7' or fpi = '8' or fpi = '9' or fpi = 'N' or fpi = 'O' or fpi = 'P' or fpi = 'Q' or fpi = 'R' or fpi = 'S' or fpi = 'T' or fpi = 'L' or fpi = 'Y')
						and intnx('day',a.rdq,-365) <= b.anndats < rdq;
        quit;

proc sort data=tmp.num_for; by gvkey rdq analys; run;
proc freq data=tmp.num_for noprint; by gvkey rdq; tables analys/out=tmp.num_for; run;

data tmp.num_for; set tmp.num_for; num_for = count; keep gvkey rdq analys num_for; run; quit;

**** BROKER SIZE ****;

data brokers; set afq; keep estimator rdq;
proc sort data=brokers nodupkey; by estimator rdq; run;

proc sql;
        create table tmp.brokersize as
        select distinct a.estimator, a.rdq, b.analys
        from brokers as a, ibes.detu_epsus as b
        where a.estimator=b.estimator and b.measure = 'EPS'
                        and (fpi = '6' or fpi = '7' or fpi = '8' or fpi = '9' or fpi = 'N' or fpi = 'O' or fpi = 'P' or fpi = 'Q' or fpi = 'R' or fpi = 'S' or fpi = 'T' or fpi = 'L' or fpi = 'Y')
						and intnx('day',a.rdq,-365) <= b.anndats < rdq;
        quit;

proc sort data=tmp.brokersize nodupkey; by estimator rdq analys; run;
proc freq data=tmp.brokersize noprint; by estimator; tables rdq/out=tmp.brokersize; run;

data tmp.brokersize; set tmp.brokersize; brokersize = count; keep estimator rdq brokersize; run; quit;

**** FIRM-SPECIFIC EXPERIENCE ****;

data firms; set afq; if ibesticker ne '' and analys ne . and gvkey ne ''; keep gvkey ibesticker analys;
proc sort data=firms nodupkey; by gvkey analys; run;

proc sql;
        create table tmp.first_firm_date as
        select a.gvkey, a.analys, b.anndats as first_firm_date
        from firms as a, ibes.detu_epsus as b
        where a.ibesticker=b.ticker and a.analys=b.analys;
        quit;

data first_firm_date; set tmp.first_firm_date; id = cat(gvkey,analys);
proc sort data=first_firm_date; by id first_firm_date; run;
data tmp.first_firm_date; set first_firm_date; by id; if first.id; keep gvkey analys first_firm_date; run; quit;

**** GENERAL EXPERIENCE ****;

data analysts; set afq; if analys ne .; keep analys;
proc sort data=analysts nodupkey; by analys; run;

proc sql;
        create table tmp.first_date as
        select a.analys, b.anndats as first_date
        from analysts as a, ibes.detu_epsus as b
        where a.analys=b.analys;
        quit;

data first_date; set tmp.first_date;
proc sort data=first_date; by analys first_date; run;
data tmp.first_date; set first_date; by analys; if first.analys; keep analys first_date; run; quit;

**** NUMBER OF INDUSTRIES COVERED BY EACH ANALYST ****;

data analysts; set afq; keep analys rdq;
proc sort data=analysts nodupkey; by analys rdq; run;

proc sql;
	create table tmp.num_industries as
    select a.analys, a.rdq, b.sic2, b.anndats
    from analysts as a, afq as b
    where a.analys=b.analys and intnx('day',a.rdq,-365) <= b.anndats < a.rdq;
    quit;

proc sort data=tmp.num_industries nodupkey; by analys rdq sic2; run;

proc freq data=tmp.num_industries noprint; by analys; tables rdq/out=tmp.num_industries; run;

data tmp.num_industries; set tmp.num_industries; num_industries = count; keep analys rdq num_industries; run; quit;

proc sort data=earn; by gvkey rdq; run;
data afq1 afq2;
	merge afq(in=a) earn(in=b);
	by gvkey rdq;
	if a eq 1 and b eq 1 then output afq1;
	if a eq 1 and b eq 0 then output afq2;
data afq; set afq1 afq2;

data first_firm_date; set tmp.first_firm_date;
proc sort data=afq; by gvkey analys; run;
proc sort data=first_firm_date; by gvkey analys; run;
data afq; merge afq(in=a) first_firm_date(in=b); by gvkey analys; if a eq 1 and b eq 1 then output afq;
data afq; set afq; firm_experience = (rdq - first_firm_date)/365;

data first_date; set tmp.first_date;
proc sort data=afq; by analys; run;
proc sort data=first_date; by analys; run;
data afq; merge afq(in=a) first_date(in=b); by analys; if a eq 1 and b eq 1 then output afq;
data afq; set afq; general_experience = (rdq - first_date)/365;

data num_industries; set tmp.num_industries;
proc sort data=afq; by analys rdq; run;
proc sort data=num_industries; by analys rdq; run;
data afq; merge afq(in=a) num_industries(in=b); by analys rdq; if a eq 1 and b eq 1 then output afq;

data num_for; set tmp.num_for;
proc sort data=afq; by gvkey rdq analys; run;
proc sort data=num_for; by gvkey rdq analys; run;
data afq; merge afq(in=a) num_for(in=b); by gvkey rdq analys; if a eq 1 and b eq 1 then output afq;

data num_companies; set tmp.num_companies;
proc sort data=afq; by analys rdq; run;
proc sort data=num_companies; by analys rdq; run;
data afq; merge afq(in=a) num_companies(in=b); by analys rdq; if a eq 1 and b eq 1 then output afq;

data brokersize; set tmp.brokersize;
proc sort data=afq; by estimator rdq; run;
proc sort data=brokersize; by estimator rdq; run;
data afq; merge afq(in=a) brokersize(in=b); by estimator rdq; if a eq 1 and b eq 1 then output afq;

data test; set afq; keep gvkey rdq analys; run;
proc sort data=test nodupkey; by gvkey rdq analys; run;

proc sql;
        create table afq123 as
        select a.gvkey, a.rdq, a.analys, afe, firm_experience, general_experience, num_for, num_companies, brokersize, num_industries, rec1, rechorizon
        from test as a, afq as b
        where a.gvkey=b.gvkey and a.rdq=b.rdq and a.analys ne b.analys;
        quit;

proc sort data=afq123; by gvkey rdq analys; run;
proc means data=afq123 noprint;
by gvkey rdq analys;
var afe firm_experience general_experience num_for num_companies brokersize num_industries rec1 rechorizon;
output out=minmax min=afe_min firm_experience_min general_experience_min num_for_min num_companies_min brokersize_min num_industries_min rec1_min rechorizon_min max=afe_max firm_experience_max general_experience_max num_for_max num_companies_max brokersize_max num_industries_max rec1_max rechorizon_max;
run;

data minmax; set minmax; keep gvkey rdq analys afe_min firm_experience_min general_experience_min num_for_min num_companies_min brokersize_min num_industries_min rec1_min rechorizon_min afe_max firm_experience_max general_experience_max num_for_max num_companies_max brokersize_max num_industries_max rec1_max rechorizon_max;

proc sort data=afq; by gvkey rdq analys; run;
proc sort data=minmax; by gvkey rdq analys; run;

data afq1 afq2;
	merge afq(in=a) minmax(in=b);
	by gvkey rdq analys;
	if a eq 1 and b eq 1 then output afq1;
	if a eq 1 and b eq 0 then output afq2;
data afq; set afq1 afq2;

data tmp.afq1;
	set afq;
	firmexp = (firm_experience - firm_experience_min)/(firm_experience_max - firm_experience_min);
	generalexp = (general_experience - general_experience_min)/(general_experience_max - general_experience_min);
	forfreq = (num_for - num_for_min)/(num_for_max - num_for_min);
	companies = (num_companies - num_companies_min)/(num_companies_max - num_companies_min);
	bsize = (brokersize - brokersize_min)/(brokersize_max - brokersize_min);
	industries = (num_industries - num_industries_min)/(num_industries_max - num_industries_min);
	accuracy = (afe_max - afe)/(afe_max - afe_min); *This one is calculated a little differently -- See Mayew (2008) footnote 12;
	abnrechorizon = (rechorizon - rechorizon_min)/(rechorizon_max - rechorizon_min);
	abnrec = (rec1 - rec1_min)/(rec1_max - rec1_min);
	if abnrec = . and rec1_min = 5 and rec1_max = 5 then abnrec = 1;
	if abnrec = . and rec1_min = 4 and rec1_max = 4 then abnrec = .75;
	if abnrec = . and rec1_min = 3 and rec1_max = 3 then abnrec = .5;
	if abnrec = . and rec1_min = 2 and rec1_max = 2 then abnrec = .25;
	if abnrec = . and rec1_min = 1 and rec1_max = 1 then abnrec = 0;

	drop afe_min firm_experience_min general_experience_min num_for_min num_companies_min brokersize_min num_industries_min rec1_min rechorizon_min afe_max firm_experience_max general_experience_max num_for_max num_companies_max brokersize_max num_industries_max rec1_max rechorizon_max;

proc download data=tmp.afq1 out=file.afq_update_20200501; run;

data firms; set tmp.firms; if permno ne .; if confcalldate ne .; keep gvkey permno confcalldate; run;
proc sort data=firms nodupkey; by permno confcalldate; run;

proc sql;
        create table tmp.prc_2_days_before_cc as
        select a.gvkey, a.confcalldate, b.date, b.prc
        from firms as a, crsp.dsf as b
        where a.permno=b.permno and intnx('weekday',a.confcalldate,-10) <= b.date <= intnx('weekday',a.confcalldate,-2);
        quit;

data prc_2_days_before_cc; set tmp.prc_2_days_before_cc; id = cat(gvkey,confcalldate); prc = abs(prc);
proc sort data=prc_2_days_before_cc; by id descending date; run;
data prc_2_days_before_cc; set prc_2_days_before_cc; by id; if first.id; keep gvkey confcalldate prc;
proc download data=prc_2_days_before_cc out=file.prc_2_days_before_cc; run;

data afq_robust; set file.afq_updating_within_90_days;
	if confcalldate ne .;
	keep gvkey analys confcalldate;
run; quit;

