data cc_ethnicity;
infile '[redacted-path-6d593a9b4419]' delimiter = ',' MISSOVER DSD lrecl=32767 firstobs=2 ;
informat filename $100.;
informat name $100.;
informat title $8.;
informat execid best32.;
informat analys best32.;
informat ethnic_code $2.;
informat religion $1.;
informat ethnic_group $1.;
informat lang_code $2.;
informat ethnic_confidence $1.;
format filename $100.;
format name $100.;
format title $8.;
format execid best12.;
format analys best12.;
format ethnic_code $2.;
format religion $1.;
format ethnic_group $1.;
format lang_code $2.;
format ethnic_confidence $1.;
input filename $ name $ title $ execid analys ethnic_code $ religion $ ethnic_group $ lang_code $ ethnic_confidence $;
run;

data cc_ethnicity;
	set cc_ethnicity;
	if ethnic_group = '' and alt_ethnic_group1 ne '' then ethnic_group = alt_ethnic_group1;
	if ethnic_group = '' and alt_ethnic_group2 ne '' then ethnic_group = alt_ethnic_group2;
proc freq data=cc_ethnicity; tables title; run;

* compute ethnicity variables;

data cc_ethnicity;
	set cc_ethnicity;

	if ethnic_group ne '';

	if ethnic_group = 'A' or ethnic_group = 'C' or ethnic_group = 'O' then asian = 1; else asian = 0;

	if ethnic_group = 'F' or ethnic_group = 'Y' or ethnic_group = 'N' or ethnic_group = 'P' or ethnic_group = 'I' then other_race = 1; else other_race = 0;

	if asian = 1 or other_race = 1 then non_white = 1; else non_white = 0;

	if ethnic_group = 'W' or ethnic_group = 'E' or ethnic_group = 'S' or ethnic_group = 'J' or ethnic_group = 'M' then white = 1; else white = 0;

	if ethnic_group = 'W' then non_white_alt = 0; else non_white_alt = 1; * if we define non-minority as western european and minority as everyone else;

	keep filename name title white non_white asian other_race non_white_alt ethnic_group;

proc sort data=cc_ethnicity; by filename; run;

data ceo_ethnicity1; set cc_ethnicity; if title = 'CEO';
data exec_ethnicity1; set cc_ethnicity; if title = 'CEO' or title = 'CFO' or title = 'IR' or title = 'OTHEXEC' or title = 'EXECUTIVE';
data analyst_ethnicity1; set cc_ethnicity; if title = 'ANALYST';

* ceo;

proc means data=ceo_ethnicity1 noprint;
by filename;
var white non_white asian other_race non_white_alt;
output out=ceo_ethnicity mean=white_ceo non_white_ceo asian_ceo other_race_ceo non_white_alt_ceo;
run;

data ceo_ethnicity;
	set ceo_ethnicity;
	if non_white_ceo > 0 then non_white_ceo = 1;
	if asian_ceo > 0 then asian_ceo = 1;
	if other_race_ceo > 0 then other_race_ceo = 1;
	if non_white_ceo = 1 then white_ceo = 0;
	if non_white_alt_ceo > 0 then non_white_alt_ceo = 1;
	keep filename white_ceo non_white_ceo asian_ceo other_race_ceo non_white_alt_ceo;

* exec;

proc means data=exec_ethnicity1 noprint;
by filename;
var white non_white asian other_race non_white_alt;
output out=exec_ethnicity mean=white_exec non_white_exec asian_exec other_race_exec non_white_alt_exec;
run;

data exec_ethnicity;
	set exec_ethnicity;
	if non_white_exec > 0 then non_white_exec = 1;
	if asian_exec > 0 then asian_exec = 1;
	if other_race_exec > 0 then other_race_exec = 1;
	if non_white_exec = 1 then white_exec = 0;
	if non_white_alt_exec > 0 then non_white_alt_exec = 1;
	keep filename white_exec non_white_exec asian_exec other_race_exec non_white_alt_exec;

* analyst;

proc means data=analyst_ethnicity1 noprint;
by filename;
var white non_white asian other_race non_white_alt;
output out=analyst_ethnicity mean=white_analyst non_white_analyst asian_analyst other_race_analyst non_white_alt_analyst;
run;

data analyst_ethnicity;
	set analyst_ethnicity;
	keep filename white_analyst non_white_analyst asian_analyst other_race_analyst non_white_alt_analyst;

data cc_ethnicity; merge exec_ethnicity analyst_ethnicity; by filename;

data test; set _null_;
%macro test123(var=,var1=);

	proc ttest data=cc_ethnicity;
	class &var;
	var white_analyst non_white_analyst asian_analyst other_race_analyst non_white_alt_analyst;
	ods output Statistics = stats;
	ods output TTests = ttests;
	run;

	proc sort data=stats; by Variable; run;

	data stats0;
		set stats;
		where Class = '0';
		mean0 = mean;
		n0 = N;
		keep Variable n0 mean0;

	data stats1;
		set stats;
		where Class = '1';
		mean1 = mean;
		n1 = N;
		keep Variable n1 mean1;

	data stats; merge stats0 stats1; by Variable;

	data ttests;
		set ttests;
		if Variances = 'Unequal';
		keep Variable tValue Probt;

	proc sort data=ttests; by Variable; run;

	data stats; merge stats ttests; by Variable;

	data stats; set stats; type = &var1;

	data test;
		set test stats;
		run; quit;


%mend;

data total_analysts;
	set file.total_analysts;
	keep filename white_analysts_total non_white_analysts_total asian_analysts_total other_race_analysts_total;
	run; quit;

proc sort data=cc_ethnicity; by filename; run;
proc sort data=total_analysts; by filename; run;

data test; merge cc_ethnicity total_analysts; by filename; run;

