run;

data ethnicity;
	set ethnicity;

	if previous_ethnicity = 'NO RACE FOUND' and corrected_ethnicity = 'Asian' then linkedin_pic_change = 'NO RACE FOUND TO ASIAN';
	if previous_ethnicity = 'NO RACE FOUND' and corrected_ethnicity = 'Black' then linkedin_pic_change = 'NO RACE FOUND TO BLACK';
